title: Limit a line to 99 units
description:
Adds MAX_QUANTITY = 99 per sku, checked in add(), with a test.

--- src/cart.js (modified, +3 −0)
@@ -1,12 +1,15 @@
 import { toCents } from "./money.js";

+export const MAX_QUANTITY = 99;
+
 export class Cart {
   #lines = new Map();

   add(sku, unitPrice, quantity = 1) {
     if (!sku) throw new Error("sku is required");
     if (!Number.isInteger(quantity) || quantity <= 0) throw new RangeError(`quantity must be a positive integer: ${quantity}`);
     const line = this.#lines.get(sku) ?? { sku, unitCents: toCents(unitPrice), quantity: 0 };
+    if (line.quantity + quantity > MAX_QUANTITY) throw new RangeError(`at most ${MAX_QUANTITY} of one sku`);
     line.quantity += quantity;
     this.#lines.set(sku, line);
     return this;

